CREATE TABLE users(id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, phone text NOT NULL DEFAULT '', password_hash text NOT NULL, role text NOT NULL DEFAULT 'customer' CHECK(role IN('customer','admin')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id text PRIMARY KEY,user_id uuid REFERENCES users(id) ON DELETE CASCADE, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE password_tokens(id text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE auth_limits(key text PRIMARY KEY, attempts int NOT NULL, until_at timestamptz NOT NULL);
CREATE TABLE addresses(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE categories(id uuid PRIMARY KEY,name text NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true);
CREATE TABLE products(id uuid PRIMARY KEY,category_id uuid REFERENCES categories(id),name text NOT NULL,description text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE variants(id uuid PRIMARY KEY,product_id uuid NOT NULL REFERENCES products(id),sku text NOT NULL UNIQUE,size text NOT NULL,color text NOT NULL,price_cents int NOT NULL CHECK(price_cents>0),stock int NOT NULL DEFAULT 0 CHECK(stock>=0),reserved int NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=stock),active boolean NOT NULL DEFAULT true,UNIQUE(product_id,size,color));
CREATE TABLE images(id uuid PRIMARY KEY,product_id uuid NOT NULL REFERENCES products(id),url text NOT NULL,position int NOT NULL DEFAULT 0);
CREATE TABLE settings(id int PRIMARY KEY CHECK(id=1),data jsonb NOT NULL);
INSERT INTO settings VALUES(1,'{"name":"Minha Loja","tagline":"Seu estilo, todos os dias.","accent":"#a4492e","logo_url":"","contact":"","policies":"Loja em configuração. Produtos e imagens demonstrativos; políticas comerciais pendentes.","pickup_enabled":false,"pickup_address":"","shipping_ranges":[],"discount_percent":0}');
CREATE TABLE orders(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),idem_key text NOT NULL,request_hash text NOT NULL,payment_status text NOT NULL DEFAULT 'pending' CHECK(payment_status IN('pending','approved','rejected','cancelled','refunded','disputed')),fulfillment_status text NOT NULL DEFAULT 'awaiting_payment' CHECK(fulfillment_status IN('awaiting_payment','ready','preparing','shipped','delivered','blocked')),subtotal_cents int NOT NULL,discount_cents int NOT NULL DEFAULT 0,shipping_cents int NOT NULL,total_cents int NOT NULL CHECK(total_cents>0),delivery jsonb NOT NULL,contact jsonb NOT NULL,expires_at timestamptz NOT NULL,stock_committed boolean NOT NULL DEFAULT false,exception text,tracking text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),reconciled_at timestamptz,UNIQUE(user_id,idem_key));
CREATE TABLE order_items(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),variant_id uuid NOT NULL REFERENCES variants(id),name text NOT NULL,sku text NOT NULL,size text NOT NULL,color text NOT NULL,quantity int NOT NULL CHECK(quantity>0),price_cents int NOT NULL CHECK(price_cents>0));
CREATE TABLE reservations(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),variant_id uuid NOT NULL REFERENCES variants(id),quantity int NOT NULL CHECK(quantity>0),status text NOT NULL DEFAULT 'held' CHECK(status IN('held','released','consumed')),expires_at timestamptz NOT NULL,UNIQUE(order_id,variant_id));
CREATE TABLE inventory_movements(id uuid PRIMARY KEY,variant_id uuid NOT NULL REFERENCES variants(id),order_id uuid REFERENCES orders(id),actor_id uuid REFERENCES users(id),delta int NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_sale_per_variant ON inventory_movements(order_id,variant_id) WHERE reason='sale';
CREATE TABLE payment_attempts(id uuid PRIMARY KEY,order_id uuid NOT NULL UNIQUE REFERENCES orders(id),preference_id text UNIQUE,checkout_url text,state text NOT NULL DEFAULT 'new',last_error text,tries int NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments(provider_id text PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),provider_status text NOT NULL,status text NOT NULL,amount_cents int NOT NULL,refunded_cents int NOT NULL DEFAULT 0,provider_updated_at timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_events(id text PRIMARY KEY,payment_id text NOT NULL,state text NOT NULL DEFAULT 'pending',attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),error text,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz);
CREATE INDEX webhook_work ON webhook_events(state,next_attempt_at);
CREATE INDEX order_user ON orders(user_id,created_at);
CREATE INDEX reservation_expiry ON reservations(status,expires_at);
CREATE INDEX order_reconcile ON orders(reconciled_at);
